#!/usr/bin/env node

/**
 * Keeps src/storage/bundled-scripts.ts in sync with assets/scripts/*.yaml.
 * The YAML files are the canonical source; the TypeScript constant is a generated
 * runtime mirror that Expo/Metro can carry without filesystem reads at runtime.
 *
 * Run automatically before web build/test/dev commands when the asset timestamps
 * are newer than the generated output or the output is missing.
 */

const fs = require("node:fs");
const path = require("node:path");

const rootDir = path.resolve(__dirname, "..");
const scriptsDir = path.join(rootDir, "assets", "scripts");
const outputFile = path.join(rootDir, "src", "storage", "bundled-scripts.ts");

function toKey(fileName) {
  return fileName.replace(/\.yaml$/, "");
}

function buildGeneratedSource(entries) {
  const lines = [
    "/**",
    " * Auto-generated from assets/scripts/*.yaml.",
    " * Do not edit this file by hand — run `node scripts/sync-bundled-scripts.js`.",
    " * The YAML files are the canonical source for bundled scripts.",
    " */",
    "",
    "export const BUNDLED_SCRIPT_TEXT: Record<string, string> = {",
  ];

  for (const [id, text] of entries) {
    lines.push(`  ${JSON.stringify(id)}: ${JSON.stringify(text)},`);
  }

  lines.push("};");
  return `${lines.join("\n")}\n`;
}

function main() {
  if (!fs.existsSync(scriptsDir)) {
    throw new Error(`Scripts directory not found: ${scriptsDir}`);
  }

  const scriptFiles = fs
    .readdirSync(scriptsDir)
    .filter((file) => file.endsWith(".yaml"))
    .sort();

  const entries = scriptFiles.map((fileName) => {
    const fullPath = path.join(scriptsDir, fileName);
    const id = toKey(fileName);
    const text = fs.readFileSync(fullPath, "utf8");
    return [id, text];
  });

  const generated = buildGeneratedSource(entries);

  let needsWrite = true;
  if (fs.existsSync(outputFile)) {
    const current = fs.readFileSync(outputFile, "utf8");
    needsWrite = current !== generated;
  }

  if (!needsWrite) {
    const assetTimes = scriptFiles.map(
      (fileName) => fs.statSync(path.join(scriptsDir, fileName)).mtimeMs,
    );
    const outputTime = fs.statSync(outputFile).mtimeMs;
    needsWrite = assetTimes.some((mtime) => mtime > outputTime);
  }

  if (needsWrite) {
    fs.writeFileSync(outputFile, generated, "utf8");
    console.log(
      `Updated ${path.relative(rootDir, outputFile)} from ${scriptFiles.length} YAML files.`,
    );
    return;
  }

  console.log(
    `Bundled scripts are up to date: ${path.relative(rootDir, outputFile)}`,
  );
}

main();
